module dram_cell_tb;

    // Testbench signals (sequential circuit)
    reg clk;
    reg [15:0] din;
    reg re;
    reg we;
    wire [15:0] dout;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    dram_cell dut (
        .clk(clk),
        .din(din),
        .re(re),
        .we(we),
        .dout(dout)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            we = 0;
            re = 0;
            din = 16'h0000;
            @(posedge clk);
            #1;

            we = 1;
            din = 16'h0000;
            @(posedge clk);
            #1;
            we = 0;
            din = 16'h0000;
            @(posedge clk);
            #1;
        end
        endtask
    task testcase001;

        begin
            reset_dut();
            test_num = test_num + 1;
            $display("Test Case %0d: Basic Write and Read", test_num);


            we = 1;
            din = 16'hABCD;
            @(posedge clk);
            #1;
            we = 0;


            re = 1;
            #1;
            #1;

            check_outputs(16'hABCD);
        end
        endtask

    task testcase002;

        begin
            reset_dut();
            test_num = test_num + 1;
            $display("Test Case %0d: Verify Write Enable functionality", test_num);


            we = 1;
            din = 16'h5555;
            @(posedge clk);
            #1;


            we = 0;
            din = 16'hAAAA;
            @(posedge clk);
            #1;


            re = 1;
            #1;
            #1;

            check_outputs(16'h5555);
        end
        endtask

    task testcase003;

        begin
            reset_dut();
