    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            intermediate <= 8'b0;  
            current_opcode <= 2'b00;  
            valid <= 1'b0;  
        end else begin  
            current_opcode <= opcode;  
            case (current_opcode)  
                2'b00: intermediate <= A + B;  
                2'b01: intermediate <= A - B;  
                2'b10: intermediate <= 8'b0;  
                default: intermediate <= 8'b0;  
            endcase  
            result <= intermediate;  
            valid <= 1'b1;  
        end  
    end  
endmodule

